kubectl -n $NSP patch pg cluster1 --type=merge -p '{"spec":{"image":"docker.io/percona/percona-distribution-postgresql:18.6.1-3","proxy":{"pgBouncer":{"image":"docker.io/percona/percona-pgbouncer:1.25.2-8"}},"backups":{"pgbackrest":{"image":"docker.io/percona/percona-pgbackrest:2.59.1-2"}}}}'
sleep 20; for i in $(seq 1 100); do sleep 5; st=$(kubectl -n $NSP get pg cluster1 -o jsonpath={.status.state}); n=$(kubectl -n $NSP get pods -l postgres-operator.crunchydata.com/instance-set=instance1 -o jsonpath='{range .items[*]}{.spec.containers[0].image}{"\n"}{end}' | grep -c 18.6.1-3); rd=$(kubectl -n $NSP get pods --no-headers | grep instance1 | grep -c 6/6); [ "$st" = ready ] && [ "$n" = 3 ] && [ "$rd" = 3 ] && break; done
echo "rolled 3 instances in $(( ($(date +%s%3N)-T)/1000 ))s state=$st"; kubectl -n $NSP exec $(pprim) -c database -- patronictl list | grep -E "Leader|Replica" | awk '{print $2,$4,$6}'
